33	
34	export default function Defects() {
35	  const { user } = useAuth();
36	  const { enqueueSnackbar } = useSnackbar();
37	  const canEdit = user.role === 'Admin' || user.role === 'Manager';
38	
39	  const [defects, setDefects] = useState([]);
40	  const [stats, setStats] = useState(null);
41	  const [loading, setLoading] = useState(true);
42	  const [search, setSearch] = useState('');
43	  const [statusFilter, setStatusFilter] = useState('');
44	  const [severityFilter, setSeverityFilter] = useState('');
45	
46	  const [formOpen, setFormOpen] = useState(false);
47	  const [editingDefect, setEditingDefect] = useState(null);
48	  const [deleteTarget, setDeleteTarget] = useState(null);
49	
50	  const load = async () => {
51	    setLoading(true);
52	    try {
53	      const [defectList, defectStats] = await Promise.all([
54	        defectApi.fetchDefects(),
55	        defectApi.fetchDefectStats(),
56	      ]);
57	      setDefects(defectList);
58	      setStats(defectStats);
59	    } catch {
60	      enqueueSnackbar('Failed to load defects - is the backend running?', { variant: 'error' });
61	    } finally {
62	      setLoading(false);
63	    }
64	  };
65	
66	  useEffect(() => {
67	    load();
68	    // eslint-disable-next-line react-hooks/exhaustive-deps
69	  }, []);
70	
71	  const filteredDefects = useMemo(() => {
72	    return defects.filter((defect) => {
73	      if (statusFilter && defect.status !== statusFilter) return false;
74	      if (severityFilter && defect.severity !== severityFilter) return false;
75	      if (search) {
76	        const haystack = `${defect.defectNo} ${defect.title} ${defect.location} ${defect.liftCode}`.toLowerCase();
77	        if (!haystack.includes(search.toLowerCase())) return false;
78	      }
79	      return true;
80	    });
81	  }, [defects, search, statusFilter, severityFilter]);
82	
83	  const handleSave = async (values) => {
84	    try {
85	      if (editingDefect) {
86	        await defectApi.updateDefect(editingDefect._id, values);
87	        enqueueSnackbar('Defect updated', { variant: 'success' });
88	      } else {
89	        await defectApi.createDefect(values);
