2	import * as Yup from 'yup';
3	import {
4	  Button,
5	  Dialog,
6	  DialogActions,
7	  DialogContent,
8	  DialogTitle,
9	  Divider,
10	  Grid,
11	  MenuItem,
12	  TextField,
13	  Typography,
14	} from '@mui/material';
15	import LiftSelect from '../lifts/LiftSelect';
16	import { DEFECT_SEVERITIES, DEFECT_NEXT_STATUSES } from '../../utils/defectHelpers';
17	
18	// Small uppercase label used to break the form into scannable sections
19	// instead of one long undifferentiated list of fields.
20	function SectionLabel({ children }) {
21	  return (
22	    <Typography
23	      variant="caption"
24	      sx={{ fontWeight: 600, letterSpacing: 0.4, color: 'text.secondary', textTransform: 'uppercase' }}
25	    >
26	      {children}
27	    </Typography>
28	  );
29	}
30	
31	const emptyDefect = {
32	  title: '',
33	  description: '',
34	  liftId: '',
35	  location: '',
36	  severity: '',
37	  reportedBy: '',
38	  status: 'Open',
39	};
40	
41	const schema = Yup.object({
42	  title: Yup.string().trim().required('Title is required'),
43	  location: Yup.string().trim().required('Location is required'),
44	  severity: Yup.string().oneOf(DEFECT_SEVERITIES).required('Severity is required'),
45	  description: Yup.string(),
46	  reportedBy: Yup.string(),
47	  status: Yup.string(),
48	});
49	
50	// Same dialog handles both Create and full Edit - editing intentionally allows
51	// correcting ANY field (title, location, severity, etc.), not just status, so a
52	// wrong initial entry can be fixed later. See defectController.js updateDefect.
53	export default function DefectFormDialog({ open, defect, onClose, onSubmit }) {
54	  const isEdit = Boolean(defect);
55	  // Status can only move to a valid next step from wherever it currently is -
56	  // mirrors the backend's VALID_TRANSITIONS so the UI never offers a change the
57	  // server would reject. On create, the field isn't shown at all (always starts Open).
58	  const nextStatusOptions = isEdit ? DEFECT_NEXT_STATUSES[defect.status] || [] : [];
59	
60	  const formik = useFormik({
61	    enableReinitialize: true,
62	    initialValues: defect
63	      ? {
64	          ...emptyDefect,
65	          ...defect,
66	          liftId: defect.liftId || '',
67	        }
68	      : emptyDefect,
69	    validationSchema: schema,
70	    onSubmit: async (values, { setSubmitting }) => {
71	      try {
72	        await onSubmit(values);
73	      } finally {
74	        setSubmitting(false);
75	      }
76	    },
77	  });
78	
79	  return (
80	    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
81	      <form onSubmit={formik.handleSubmit}>
82	        <DialogTitle>{isEdit ? `Edit Defect ${defect.defectNo}` : 'Log Defect'}</DialogTitle>
83	        <DialogContent dividers>
84	          {/* Section: what the defect is */}
85	          <SectionLabel>Defect Details</SectionLabel>
86	          <Grid container spacing={2} sx={{ mt: 1, mb: 2.5 }}>
87	            <Grid size={12}>
88	              <TextField
89	                name="title"
90	                label="Title"
91	                placeholder="e.g., Door not closing fully"
92	                fullWidth
93	                value={formik.values.title}
94	                onChange={formik.handleChange}
95	                error={formik.touched.title && Boolean(formik.errors.title)}
96	                helperText={formik.touched.title && formik.errors.title}
97	              />
98	            </Grid>
99	            <Grid size={12}>
100	              <TextField
101	                name="description"
102	                label="Description"
103	                placeholder="Describe the defect..."
104	                fullWidth
105	                multiline
106	                rows={3}
107	                value={formik.values.description}
108	                onChange={formik.handleChange}
109	              />
110	            </Grid>
111	          </Grid>
112	
113	          <Divider />
114	
115	          {/* Section: where it is and how serious it is */}
116	          <SectionLabel>Location &amp; Classification</SectionLabel>
117	          <Grid container spacing={2} sx={{ mt: 1, mb: 2.5 }}>
118	            <Grid size={12}>
119	              <TextField
120	                name="location"
121	                label="Location"
122	                placeholder="e.g., Blk 12 lift lobby"
123	                fullWidth
124	                value={formik.values.location}
125	                onChange={formik.handleChange}
126	                error={formik.touched.location && Boolean(formik.errors.location)}
127	                helperText={formik.touched.location && formik.errors.location}
128	              />
129	            </Grid>
130	            <Grid size={12}>
131	              <LiftSelect
132	                value={formik.values.liftId}
133	                onChange={(id) => formik.setFieldValue('liftId', id)}
134	                label="Lift"
135	              />
136	            </Grid>
137	            <Grid size={isEdit ? 6 : 12}>
138	              <TextField
139	                select
140	                name="severity"
141	                label="Severity"
142	                fullWidth
143	                value={formik.values.severity}
144	                onChange={formik.handleChange}
145	                error={formik.touched.severity && Boolean(formik.errors.severity)}
146	                helperText={formik.touched.severity && formik.errors.severity}
147	                sx={{ '& .MuiSelect-select': { minWidth: 120 } }}
148	              >
149	                {DEFECT_SEVERITIES.map((s) => (
150	                  <MenuItem key={s} value={s}>
151	                    {s}
152	                  </MenuItem>
153	                ))}
154	              </TextField>
155	            </Grid>
156	            {isEdit && (
157	              <Grid size={6}>
158	                <TextField
159	                  select
160	                  name="status"
161	                  label="Status"
162	                  fullWidth
163	                  value={formik.values.status}
164	                  onChange={formik.handleChange}
165	                  sx={{ '& .MuiSelect-select': { minWidth: 120 } }}
166	                >
167	                  <MenuItem value={defect.status}>{defect.status} (no change)</MenuItem>
168	                  {nextStatusOptions.map((s) => (
169	                    <MenuItem key={s} value={s}>
170	                      {s}
171	                    </MenuItem>
172	                  ))}
173	                </TextField>
174	              </Grid>
175	            )}
176	          </Grid>
177	
178	          <Divider />
179	
180	          {/* Section: who's logging it */}
181	          <SectionLabel>Reporting</SectionLabel>
182	          <Grid container spacing={2} sx={{ mt: 1 }}>
183	            <Grid size={12}>
184	              <TextField
185	                name="reportedBy"
186	                label="Reported By"
187	                placeholder="e.g., Building Manager"
188	                fullWidth
189	                value={formik.values.reportedBy}
190	                onChange={formik.handleChange}
191	              />
192	            </Grid>
193	          </Grid>
194	        </DialogContent>
195	        <DialogActions>
196	          <Button onClick={onClose} disabled={formik.isSubmitting}>
197	            Cancel
198	          </Button>
199	          <Button type="submit" variant="contained" disabled={formik.isSubmitting}>
200	            {isEdit ? 'Save Changes' : 'Log Defect'}
201	          </Button>
202	        </DialogActions>
203	      </form>
204	    </Dialog>
205	  );
206	}

