1	import { useEffect, useState } from 'react';
2	import { Autocomplete, TextField } from '@mui/material';
3	import { fetchLifts } from '../../api/liftApi';
4	
5	/**
6	 * Live lift picker shared by Schedule/Inspection/Defect forms so every module links to a real
7	 * Lift document instead of a hardcoded placeholder ID or free-text lift code.
8	 */
9	export default function LiftSelect({ value, onChange, error, helperText, label = 'Lift', disabled }) {
10	  const [lifts, setLifts] = useState([]);
11	  const [loading, setLoading] = useState(true);
12	
13	  useEffect(() => {
14	    fetchLifts()
15	      .then(setLifts)
16	      // Lifts might not be mounted in server.js yet (each feature owner mounts
17	      // their own router) — degrade to an empty picker instead of an unhandled
18	      // rejection so forms embedding this can still be used with manual entry.
19	      .catch(() => setLifts([]))
20	      .finally(() => setLoading(false));
21	  }, []);
22	
23	  const selected = lifts.find((l) => l._id === value) || null;
24	
25	  return (
26	    <Autocomplete
27	      options={lifts}
28	      loading={loading}
29	      disabled={disabled}
30	      value={selected}
31	      getOptionLabel={(lift) => `${lift.liftCode} — Blk ${lift.block}, ${lift.unit}`}
32	      isOptionEqualToValue={(option, val) => option._id === val._id}
33	      // Second onChange arg passes the full lift record (beyond just its id)
34	      // so consuming forms can auto-fill dependent fields (e.g. Scheduling
35	      // copying the lift's block into its own Block/Lift Address field).
